-- Comentarios de tabla y columna de Finance AI (descripciones del diccionario de datos).
-- Aplicar sobre la base `finance_ai` ya migrada (alembic upgrade head). Solo agrega metadatos.
BEGIN;
COMMENT ON TABLE public.account IS 'Cuentas donde la persona guarda su dinero (efectivo, banco, billetera digital, ahorros, tarjeta de crédito u otra). El saldo actual no se almacena: se calcula.';
COMMENT ON COLUMN public.account.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.account.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.account.name IS 'Nombre de la cuenta; único entre las cuentas activas de la persona, sin distinguir mayúsculas.';
COMMENT ON COLUMN public.account.type IS 'Tipo de cuenta: cash, bank, digital_wallet, savings, credit_card u other.';
COMMENT ON COLUMN public.account.currency_id IS 'Moneda del registro (clave foránea a currency).';
COMMENT ON COLUMN public.account.opening_balance IS 'Saldo inicial con signo (negativo representa deuda). El saldo actual se calcula.';
COMMENT ON COLUMN public.account.is_active IS 'Falso cuando la cuenta fue desactivada; conserva su historial.';
COMMENT ON COLUMN public.account.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.account.updated_at IS 'Fecha y hora de la última modificación.';
COMMENT ON TABLE public.account_movement IS 'Efecto firmado de una transacción sobre una cuenta. El saldo actual de una cuenta es su saldo inicial más la suma de estos movimientos confirmados.';
COMMENT ON COLUMN public.account_movement.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.account_movement.user_id IS 'Propietario; junto con la cuenta y la transacción garantiza que ambas pertenezcan a la misma persona.';
COMMENT ON COLUMN public.account_movement.transaction_id IS 'Transacción que originó el movimiento (clave foránea a financial_transaction).';
COMMENT ON COLUMN public.account_movement.account_id IS 'Cuenta afectada (clave foránea a account).';
COMMENT ON COLUMN public.account_movement.amount IS 'Monto con signo (positivo acredita, negativo debita); no puede ser cero.';
COMMENT ON COLUMN public.account_movement.created_at IS 'Fecha y hora de creación.';
COMMENT ON TABLE public.app_user IS 'Personas registradas. Guarda el correo normalizado, el hash de la contraseña y la moneda preferida.';
COMMENT ON COLUMN public.app_user.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.app_user.email IS 'Correo electrónico normalizado (minúsculas y sin espacios); único.';
COMMENT ON COLUMN public.app_user.password_hash IS 'Hash Argon2 de la contraseña; la contraseña nunca se almacena.';
COMMENT ON COLUMN public.app_user.role_id IS 'Rol de la persona (clave foránea a role).';
COMMENT ON COLUMN public.app_user.preferred_currency_id IS 'Moneda preferida de la persona (clave foránea a currency).';
COMMENT ON COLUMN public.app_user.is_active IS 'Indica si el registro está activo; al desactivarlo se conserva el historial.';
COMMENT ON COLUMN public.app_user.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.app_user.updated_at IS 'Fecha y hora de la última modificación.';
COMMENT ON TABLE public.budget IS 'Presupuestos de gasto: alcance (todos los gastos o una categoría), calendario recurrente o de una sola vez, monto y moneda. El avance se calcula al consultar.';
COMMENT ON COLUMN public.budget.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.budget.user_id IS 'Propietario; junto con la categoría garantiza que la categoría sea de la misma persona.';
COMMENT ON COLUMN public.budget.currency_id IS 'Moneda del registro (clave foránea a currency).';
COMMENT ON COLUMN public.budget.category_id IS 'Categoría que limita el presupuesto; nulo significa todos los gastos.';
COMMENT ON COLUMN public.budget.name IS 'Nombre del presupuesto (opcional en la aplicación).';
COMMENT ON COLUMN public.budget.amount IS 'Monto objetivo; mayor que cero.';
COMMENT ON COLUMN public.budget.schedule_type IS 'Calendario: recurring (recurrente) o one_time (una sola vez).';
COMMENT ON COLUMN public.budget.frequency_unit IS 'Unidad de repetición: day, week, month o year; solo si es recurrente.';
COMMENT ON COLUMN public.budget.frequency_interval IS 'Cada cuántas unidades se repite (1 a 999); solo si es recurrente.';
COMMENT ON COLUMN public.budget.starts_on IS 'Fecha de inicio.';
COMMENT ON COLUMN public.budget.ends_on IS 'Fecha de fin; nulo significa sin fin. No puede ser anterior al inicio.';
COMMENT ON COLUMN public.budget.is_active IS 'Indica si el registro está activo; al desactivarlo se conserva el historial.';
COMMENT ON COLUMN public.budget.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.budget.updated_at IS 'Fecha y hora de la última modificación.';
COMMENT ON TABLE public.category IS 'Categorías de gasto definidas por cada persona, con color, ícono y orden de presentación.';
COMMENT ON COLUMN public.category.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.category.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.category.name IS 'Nombre de la categoría, sin espacios en los extremos.';
COMMENT ON COLUMN public.category.color IS 'Color de la etiqueta: azul, verde, naranja, morado, rosa, rojo, turquesa, amarillo o gris (en inglés en la base).';
COMMENT ON COLUMN public.category.icon IS 'Identificador del ícono, dentro de un conjunto cerrado (alimentación, transporte, hogar, salud, etc.).';
COMMENT ON COLUMN public.category.sort_order IS 'Posición de la categoría en la lista; no negativa.';
COMMENT ON COLUMN public.category.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.category.updated_at IS 'Fecha y hora de la última modificación.';
COMMENT ON TABLE public.currency IS 'Monedas admitidas (código ISO 4217, nombre y decimales).';
COMMENT ON COLUMN public.currency.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.currency.code IS 'Código ISO 4217 de la moneda (por ejemplo COP); único.';
COMMENT ON COLUMN public.currency.name IS 'Nombre del registro.';
COMMENT ON COLUMN public.currency.decimals IS 'Número de decimales de la moneda.';
COMMENT ON COLUMN public.currency.is_active IS 'Indica si el registro está activo; al desactivarlo se conserva el historial.';
COMMENT ON TABLE public.expense IS 'Renglones (ítems) de un recibo o gasto: nombre, cantidad, precio unitario y monto.';
COMMENT ON COLUMN public.expense.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.expense.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.expense.receipt_id IS 'Recibo al que pertenece el renglón (clave foránea a receipt).';
COMMENT ON COLUMN public.expense.subcategory_id IS 'Subcategoría del renglón; opcional.';
COMMENT ON COLUMN public.expense.category_id IS 'Categoría del renglón; opcional.';
COMMENT ON COLUMN public.expense.position IS 'Posición del renglón dentro del recibo; única por recibo.';
COMMENT ON COLUMN public.expense.name IS 'Descripción del ítem o concepto.';
COMMENT ON COLUMN public.expense.quantity IS 'Cantidad (hasta tres decimales); mayor que cero.';
COMMENT ON COLUMN public.expense.unit_price IS 'Precio unitario; opcional.';
COMMENT ON COLUMN public.expense.amount IS 'Monto del renglón; mayor que cero.';
COMMENT ON COLUMN public.expense.item_reason IS 'Motivo del ítem (texto libre).';
COMMENT ON COLUMN public.expense.note IS 'Nota adicional.';
COMMENT ON COLUMN public.expense.image_path IS 'Referencia a una imagen adjunta al renglón.';
COMMENT ON COLUMN public.expense.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.expense.updated_at IS 'Fecha y hora de la última modificación.';
COMMENT ON TABLE public.financial_transaction IS 'Transacción financiera confirmada, pendiente o anulada (gasto, ingreso, transferencia o ajuste). Es la cabecera común de todo movimiento de dinero.';
COMMENT ON COLUMN public.financial_transaction.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.financial_transaction.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.financial_transaction.income_source_id IS 'Fuente de ingreso (solo para transacciones de tipo income).';
COMMENT ON COLUMN public.financial_transaction.source_proposal_id IS 'Borrador de IA del que proviene la transacción; con user_id es único y hace idempotente la confirmación.';
COMMENT ON COLUMN public.financial_transaction.type IS 'Tipo: expense, income, transfer o adjustment.';
COMMENT ON COLUMN public.financial_transaction.status IS 'Estado: pending, confirmed o voided. Solo las confirmadas afectan los saldos.';
COMMENT ON COLUMN public.financial_transaction.occurred_at IS 'Fecha y hora en que ocurrió el movimiento.';
COMMENT ON COLUMN public.financial_transaction.description IS 'Descripción libre del movimiento.';
COMMENT ON COLUMN public.financial_transaction.capture_source IS 'Origen del registro: manual, ai, text_ai, audio_ai, receipt_photo_ai o import.';
COMMENT ON COLUMN public.financial_transaction.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.financial_transaction.updated_at IS 'Fecha y hora de la última modificación.';
COMMENT ON TABLE public.income IS 'Ingresos del diseño inicial (monto, fecha y fuente global). Se conserva por compatibilidad: la aplicación actual registra los ingresos como transacciones financieras de tipo income.';
COMMENT ON COLUMN public.income.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.income.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.income.income_source_id IS 'Fuente global del ingreso (clave foránea a incomesource).';
COMMENT ON COLUMN public.income.currency_id IS 'Moneda del registro (clave foránea a currency).';
COMMENT ON COLUMN public.income.amount IS 'Monto del ingreso; mayor que cero.';
COMMENT ON COLUMN public.income.date IS 'Fecha del ingreso.';
COMMENT ON COLUMN public.income.description IS 'Descripción libre.';
COMMENT ON TABLE public.income_source IS 'Fuentes de ingreso propias de cada persona (por ejemplo salario). Las usan las transacciones de tipo ingreso.';
COMMENT ON COLUMN public.income_source.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.income_source.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.income_source.name IS 'Nombre de la fuente de ingreso.';
COMMENT ON COLUMN public.income_source.is_active IS 'Indica si el registro está activo; al desactivarlo se conserva el historial.';
COMMENT ON COLUMN public.income_source.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.income_source.updated_at IS 'Fecha y hora de la última modificación.';
COMMENT ON TABLE public.incomesource IS 'Catálogo global de fuentes de ingreso del diseño inicial; lo usa la tabla income. Se conserva por compatibilidad: los ingresos actuales usan income_source.';
COMMENT ON COLUMN public.incomesource.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.incomesource.name IS 'Nombre de la fuente global; único.';
COMMENT ON TABLE public.paymentmethod IS 'Catálogo de métodos de pago asociados a los recibos (efectivo, tarjeta, etc.).';
COMMENT ON COLUMN public.paymentmethod.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.paymentmethod.name IS 'Nombre del método de pago; único.';
COMMENT ON TABLE public.receipt IS 'Cabecera de un recibo o gasto manual: comercio, fecha, moneda, total, método de pago y vínculo con la transacción financiera.';
COMMENT ON COLUMN public.receipt.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.receipt.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.receipt.transaction_id IS 'Transacción financiera asociada (clave foránea a financial_transaction).';
COMMENT ON COLUMN public.receipt.store_id IS 'Comercio normalizado (clave foránea a store); opcional.';
COMMENT ON COLUMN public.receipt.store IS 'Nombre del comercio mostrado en el recibo.';
COMMENT ON COLUMN public.receipt.date IS 'Fecha del comprobante.';
COMMENT ON COLUMN public.receipt.currency_id IS 'Moneda del registro (clave foránea a currency).';
COMMENT ON COLUMN public.receipt.category_id IS 'Categoría general del recibo; opcional.';
COMMENT ON COLUMN public.receipt.purchase_reason IS 'Motivo de la compra (texto libre).';
COMMENT ON COLUMN public.receipt.total IS 'Total del recibo; mayor que cero.';
COMMENT ON COLUMN public.receipt.payment_method_id IS 'Método de pago (clave foránea a paymentmethod).';
COMMENT ON COLUMN public.receipt.image IS 'Referencia a la imagen adjunta; el servidor no conserva el archivo.';
COMMENT ON COLUMN public.receipt.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.receipt.updated_at IS 'Fecha y hora de la última modificación.';
COMMENT ON TABLE public.receipt_proposals IS 'Borradores de captura de recibos con IA (JSON de la propuesta, revisión y vencimiento). Nada se guarda como gasto hasta que la persona confirma.';
COMMENT ON COLUMN public.receipt_proposals.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.receipt_proposals.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.receipt_proposals.status IS 'Estado del borrador: complete, partial, not_a_receipt, failed_extraction, confirmed o discarded.';
COMMENT ON COLUMN public.receipt_proposals.proposal_data IS 'Contenido de la propuesta en formato JSON.';
COMMENT ON COLUMN public.receipt_proposals.revision IS 'Número de revisión del borrador.';
COMMENT ON COLUMN public.receipt_proposals.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.receipt_proposals.expires_at IS 'Vencimiento del borrador.';
COMMENT ON TABLE public.renewable_credential IS 'Credenciales renovables de una sesión. Cada renovación consume la credencial vigente y emite otra (rotación); solo se guarda su hash.';
COMMENT ON COLUMN public.renewable_credential.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.renewable_credential.session_id IS 'Sesión a la que pertenece la credencial (clave foránea a user_session).';
COMMENT ON COLUMN public.renewable_credential.token_hash IS 'Hash SHA-256 de la credencial renovable; único.';
COMMENT ON COLUMN public.renewable_credential.issued_at IS 'Fecha y hora de emisión.';
COMMENT ON COLUMN public.renewable_credential.expires_at IS 'Fecha y hora de vencimiento (posterior a la emisión).';
COMMENT ON COLUMN public.renewable_credential.consumed_at IS 'Momento en que se usó para renovar; nulo si sigue vigente.';
COMMENT ON COLUMN public.renewable_credential.replaced_by_id IS 'Credencial que la reemplazó al rotar (autorreferencia).';
COMMENT ON TABLE public.role IS 'Roles de la aplicación (por ejemplo user y admin). Cada usuario tiene exactamente un rol.';
COMMENT ON COLUMN public.role.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.role.name IS 'Nombre del rol (único).';
COMMENT ON TABLE public.spendinglimit IS 'Límites de gasto semanales o mensuales del diseño inicial. La aplicación actual gestiona sus presupuestos en budget; la tabla se conserva por compatibilidad.';
COMMENT ON COLUMN public.spendinglimit.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.spendinglimit.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.spendinglimit.name IS 'Nombre del límite.';
COMMENT ON COLUMN public.spendinglimit.amount IS 'Monto máximo; mayor que cero.';
COMMENT ON COLUMN public.spendinglimit.period IS 'Período: weekly o monthly.';
COMMENT ON COLUMN public.spendinglimit.subcategory_id IS 'Subcategoría limitada; exactamente una de subcategoría o categoría.';
COMMENT ON COLUMN public.spendinglimit.category_id IS 'Categoría limitada; exactamente una de subcategoría o categoría.';
COMMENT ON TABLE public.store IS 'Comercios normalizados por persona, para reutilizarlos entre recibos.';
COMMENT ON COLUMN public.store.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.store.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.store.name IS 'Nombre del comercio tal como se registró.';
COMMENT ON COLUMN public.store.normalized_name IS 'Nombre normalizado para detectar duplicados; único por persona.';
COMMENT ON COLUMN public.store.is_active IS 'Indica si el registro está activo; al desactivarlo se conserva el historial.';
COMMENT ON TABLE public.subcategory IS 'Subcategorías opcionales dentro de una categoría.';
COMMENT ON COLUMN public.subcategory.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.subcategory.category_id IS 'Categoría a la que pertenece (clave foránea a category).';
COMMENT ON COLUMN public.subcategory.name IS 'Nombre de la subcategoría.';
COMMENT ON TABLE public.text_capture_proposals IS 'Borradores de captura por texto o voz con IA. Vencen a las 24 horas y solo los ve su dueño.';
COMMENT ON COLUMN public.text_capture_proposals.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.text_capture_proposals.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.text_capture_proposals.status IS 'Estado del borrador (por ejemplo ready, needs_clarification, unrecognized, confirmed o discarded).';
COMMENT ON COLUMN public.text_capture_proposals.proposal_data IS 'Contenido de la propuesta en formato JSON.';
COMMENT ON COLUMN public.text_capture_proposals.revision IS 'Número de revisión del borrador.';
COMMENT ON COLUMN public.text_capture_proposals.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.text_capture_proposals.expires_at IS 'Vencimiento del borrador (24 horas).';
COMMENT ON TABLE public.user_session IS 'Sesiones de acceso por dispositivo. Almacena solo el hash del token de acceso y sus tres vencimientos (acceso, inactividad y absoluto).';
COMMENT ON COLUMN public.user_session.id IS 'Identificador interno de la fila (clave primaria).';
COMMENT ON COLUMN public.user_session.user_id IS 'Persona propietaria del registro (clave foránea a app_user); toda consulta filtra por este valor.';
COMMENT ON COLUMN public.user_session.access_token_hash IS 'Hash SHA-256 del token de acceso (64 caracteres hexadecimales); único.';
COMMENT ON COLUMN public.user_session.platform IS 'Plataforma del cliente que abrió la sesión: android o windows.';
COMMENT ON COLUMN public.user_session.access_expires_at IS 'Vencimiento del token de acceso (15 minutos por defecto).';
COMMENT ON COLUMN public.user_session.idle_expires_at IS 'Vencimiento por inactividad (30 días por defecto).';
COMMENT ON COLUMN public.user_session.absolute_expires_at IS 'Vencimiento absoluto de la sesión (90 días por defecto).';
COMMENT ON COLUMN public.user_session.created_at IS 'Fecha y hora de creación.';
COMMENT ON COLUMN public.user_session.last_renewed_at IS 'Última renovación de la sesión.';
COMMENT ON COLUMN public.user_session.revoked_at IS 'Fecha de revocación; nulo mientras la sesión siga vigente.';
COMMENT ON COLUMN public.user_session.revocation_reason IS 'Motivo de la revocación (por ejemplo logout o session_limit); obligatorio cuando existe revoked_at.';
COMMIT;
